;window.__RUJ={"dn1":"ночь","dn2":"рассвет","dn3":"день","dn4":"закат","dn5":"Сейчас в Донецке","dn6":"Тема: по времени Донецка","dn7":"Тема: светлая","dn8":"Тема: тёмная","dn9":"Сайт живёт по донецкому времени: ночью в Донецке он темнеет.","n1":"Главная","n6":"Пресса","qz0":"Квиз","at0":"Атлас","tr0":"Трамвай №1","oc0":"Октябрь 2011","mn7":"Показать весь журнал","mn8":"Свернуть журнал","ql3":"Играть","ql4":"{n} раундов · ~{m} мин","ql5":"Без регистрации","ql7":"Четыре варианта на снимок. Узнай место с одного взгляда.","ql8":"Поставь точку на карте города. Чем ближе, тем больше очков.","ql9":"До, в или после 2011 года? Город менялся быстро.","ql10":"Одно фото на всех и одна попытка. Возвращайся каждый день.","ql11":"← Все режимы","ql12":"Счёт","ql13":"{n} фото 2008–2013 годов","ql14":"Сыграно партий: {n}","ql15":"Рекорда пока нет","ql16":"Сегодня сыграно ✓","ql17":"Другой режим","ql18":"Итог","qz1":"Угадай место","qz2":"Где это на карте?","qz3":"Угадай год","qz4":"Фото дня","qz9":"Ответить","qz10":"Поставь точку на карте: где сделан снимок?","qz12":"До 2011","qz13":"В 2011","qz14":"После 2011","qz15":"Снято {d}","qz16":"{km} от цели · +{p}","qz17":"Счёт: {p} из {max}","qz18":"Угадали {p}% игроков · ответов: {n}","qz19":"Ты среди первых: ответов пока {n}","qz20":"Фото дня №{n}","qz21":"Одно фото на всех и одна попытка. Новое фото каждый день.","qz22":"Поделиться результатом","qz23":"Скопировано","qz24":"новое фото через {t}","qz25":"Серия: {n} дн.","qz26":"{p}% игроков попали ближе 1,5 км · ответов: {n}","qz27":"{n} м","qz28":"{n} км","qz29":"Правильное место","qz30":"Твой ответ","qz31":"Приблизить карту","qz32":"Отдалить карту","qz33":"Карта © участники OpenStreetMap (ODbL)","qz34":"Лучший счёт: {b}","ar0":"Все","ar1":"С высоты","ar2":"Улицы","ar3":"Парки","ar4":"Здания","ar5":"Стадион","ar6":"{n} фото","ar7":"Закрыть","ar8":"Предыдущее фото","ar9":"Следующее фото","ar10":"Оригинал на Wikimedia Commons ↗","g40":"Проспект Ильича","g41":"Улица Артёма","g42":"Лучший результат: {b} из {n}","q61":"Свернуть","q63":"15 октября 2011, {t}","rn1":"3D-модель квартала · OSM + SRTM","g4":"Начать","g5":"Ещё раз","g6":"Верно.","g7":"Нет, это {x}.","g8":"Дальше →","g9":"{s} из {n}","g10":"Парк Щербакова","g11":"«Донбасс Арена»","g12":"Бульвар Пушкина","g13":"Ворошиловский район","g14":"Театр оперы и балета","g15":"Ты помнишь этот город.","g17":"Город ещё узнаётся.","g18":"Город ждёт, чтобы его вспомнили.","g16":"Фото {i} из {n}","g20":"новое","sp10":"Фото для Donetsk 2011","sp11":"Что на фото","sp12":"Где: улица, район","sp13":"Когда: год, месяц","sp14":"Как подписать автора","sp15":"Я автор этих фото и разрешаю опубликовать их на сайте и в игре Donetsk 2011 под лицензией CC BY-SA 4.0 с указанием моего авторства.","at9":"Нажми на точку на карте, чтобы увидеть снимки этого места.","at6":"Открыть в «Тогда и потом» →","at7":"{n} фото здесь","at8":"{n} мест на карте","at12":"Точка примерная: место съёмки взято из описания снимка на Commons.","at13":"Вид с Green Plaza","at14":"Вид с облгосадминистрации","pl3":"Поделиться","pc9":"Отправить открытку","pl4":"Ссылка скопирована","at10":"Угадаешь это место в игре? →","tr37":"Сейчас в Донецке","tr3":"Поехали","tr4":"Пауза","tr6":"Следующая:","tr7":"Остановка","tr13":"Конечная","tr31":"За окном","tr38":"День","tr39":"Вечер","tr40":"Ночь","tr32":"от пути","oc20":"Средняя","oc21":"Осадки, мм","oc22":"{d} октября","oc23":"без осадков","mm1":"Карта памяти","mm5":"Нажми на карту, чтобы выбрать место","mm12":"Одобренных воспоминаний пока нет. Стань первым.","mm13":"Воспоминаний на карте: {n}","mm14":"Дом 33 · здесь начинается проект","mm20":"Выбрано: {lat}, {lon}","mm25":"Место","mm26":"Год","mm27":"Координаты","mm28":"Воспоминание","mm29":"Подпись","mm30":"Я согласен(на), что запись может появиться на сайте Donetsk 2011, и в ней нет чужих личных данных.","mm31":"Выбери точку на карте и отметь согласие","gr1":"Знаешь это место? Добавь воспоминание на карту →","sr2":"Ничего не нашлось. Попробуйте другое слово.","sr4":"Найдено: {n}","sr8":"Загрузка…","t57":"Блокаут","m1":"Конфликт C-04 открыт","m2":"Белые линии: сегодняшняя карта OSM. Оранжевые: версии той же базы, действовавшие в июле 2011 года. Расхождение доходит до 3,23 м на Заречной и 7,92 м на Донецкой. Это не доказывает, что дороги сдвинулись: могла измениться точность карты. Обе версии сохранены, пока спор не решит датированный источник.","cm1":"Было","cm2":"Стало","m3":"Сравнение планов OSM: сегодня и июль 2011","hp15":"Ссылка скопирована ✓","w2":"Город, недосягаемый для миллионов","gv1":"Гости Донецка 2011","gv5":"Другие страны","gv6":"Ты зашёл из: {c}. Спасибо, что заглянул.","gv7":"Пока пусто. Ты можешь стать первым гостем.","q98":"Эталонная карта","q70":"Фасады","q60":"На весь экран","q73":"Здания, улицы и рельеф взяты из OpenStreetMap и SRTM. Трамвайная линия на проспекте Дзержинского взята из OpenStreetMap: два пути на отдельном полотне между проезжими частями и контактный провод. В 2011 году по ней ходили маршруты 9 и 10 на вагонах Tatra T3SU; окраска показана заводская, красно-кремовая. На Заречной у домов 25–38 цвет стен и крыш, форма крыш, заборы, цвет ворот, обочина и газовая труба взяты из записей по панорамам октября 2011 года. На остальных участках заборы, деревья, столбы и окна типичны для частного сектора Донецка, но не сверены с фото каждого дома; машины на улицах условные. Выключи «Фасады», и цвет снова покажет, что известно: тёплые объёмы стоят условные 3,2 м, серые — высота по этажам OSM. Малиновые — детальный этюд у дома 33.","q99":"из тега height в OSM","q101":"Производственное здание","q102":"Общественное или торговое здание","q103":"Храм","q104":"Киоск или павильон","q105":"Здание, назначение в OSM не указано","q106":"Эталонная карта проекта 4,37 × 2,84 км вокруг квартала: {b} зданий, дороги, рельсы, вода и деревья из OpenStreetMap (выгрузка 22.09.2026). Это современные данные, для 2011 года они не проверены. Высоту по этажности или тегу height в OSM имеют {l} зданий, остальные стоят с типичной для своего типа высотой. Нажми на любой дом.","q107":"Рельеф: SRTM 2000 года, шаг 3″ (≈ 62 × 93 м).","q108":"Рельеф за пределами квартала пока условный: данные SRTM для всей карты подтянутся при следующем обновлении сайта.","q109":"Эталонная карта: контуры зданий, дороги, рельсы и вода из современного OSM (F). Этажность взята из OSM (F), посчитана по панорамам Street View октября 2011 года (B) или оценена по типу здания и соседям (E). Деревья вдоль улиц, машины во дворах, палатки, ларьки, подъезды и вагоны расставлены условно.","q110":"{n} этажей по панораме Street View октября 2011 года","q111":"Движение — мини-симуляция: до {c} машин и маршруток, автобусы и {t} трамваев ездят по улицам карты с учётом односторонних улиц и полос. {s} перекрёстков со светофорами, {bs} автобусных и {ts} трамвайных остановок — по OpenStreetMap на сентябрь 2012 года, ближайшему к 2011-му сохранившемуся состоянию. Машины, маршруты и фазы светофоров условные; ночью машин меньше, в часы пик больше — двигай ползунок солнца. Разметка, стоп-линии и зебры нарисованы у светофоров и у переходов из OSM 2012; тротуары и фонари вдоль главных улиц, павильоны на остановках и деревья в парках и лесах расставлены условно.","q112":"по соседним домам той же формы с известной этажностью, оценка","q113":"Троллейбусы: {tb} машин ездят под контактной сетью по улицам троллейбусных маршрутов — Артёма, Ленинскому проспекту, Университетской. Маршруты взяты из современного OSM, но сеть на этих улицах та же, что была в 2011 году (класс C). Пешеходы ({p}) ходят по тротуарам главных улиц и переходят дорогу по зебрам, когда у машин красный. ЛЭП на 35 и 110 кВ с опорами, заводские трубы и водонапорная башня тоже из современного OSM; высота труб оценена по их диаметру (E). Деревья вдоль улиц и машины во дворах расставлены условно.","q114":"Класса A здесь пока нет. Класс B есть только у этажности {n} зданий: её посчитали по панорамам 2011 года.","q115":"Движение и детали карты","q86":"Тип","q96":"по тегам OSM","q97":"оценка по площади и адресу","q87":"Жилой дом","q88":"Хозпостройка","q89":"Гаражи","q90":"Навес","q91":"Трансформаторная подстанция (ТП)","q92":"Подстанция 110 кВ «Кальмиусская»","q93":"Нежилое здание","q94":"Многоквартирный дом","q95":"типичная для такого здания, оценка","q71":"Фасад","q72":"условно, по типу дома, не по фото","q18":"Модель","q16":"Нажми «Управлять 3D», затем: один палец вращает, двумя пальцами масштабируй и двигай · малиновые цифры открывают панорамы 2011","q19":"Карточка дома","q20":"Нажми на любой дом","q21":"Тёплые объёмы: высота неизвестна, стоят условные 3,2 м. Серые: высота по числу этажей в OSM. Малиновые: детальный этюд у дома 33.","q22":"Адрес в OSM не указан","q23":"Контур","q24":"современный OSM, для 2011 года не проверен","q25":"Высота","q26":"по числу этажей в OSM, 3 м на этаж","q27":"неизвестна, условный объём","q28":"Площадь контура","q29":"Открыть в OpenStreetMap ↗","q30":"Северный ориентир. В базе OSM 2012 года он уже был, позже контур сдвинули примерно на 5,8 м. Это правка карты, а не переезд дома. Светлая стена изучена по панораме октября 2011 года.","q31":"В базе OSM 2012 года этот дом уже был. Позже контур сдвинули примерно на 4,8 м и добавили 5 этажей.","q32":"Подстанция. В базе OSM 2012 года уже была, позже контур сдвинули примерно на 3,2 м.","q33":"Детальный этюд","q34":"Здесь стоит подробная модель: ворота с калиткой, бетонный забор, кирпичный объём и серая пристройка. В этой сцене показан только контур OSM, сама модель живёт в Unreal.","q35":"Смотреть кадры из Unreal ↓","q36":"Панорама {n} · октябрь 2011 ↗","q37":"авторская модель по панорамам 2011","q38":"м","q39":"м²","q40":"Классы достоверности в этой сцене","q41":"Контуры 189 зданий и оси улиц: современный OSM","q42":"Высоты: 9 по этажности OSM, 23 по типу здания в OSM (гаражи, подстанции, навес) и 157 условных, этюд у дома 33","q43":"Рельеф SRTM и линии OSM на июль 2011 года","q44":"Классов A и B здесь пока нет. Так честно выглядит начало: сначала оценки, потом доказательства.","q50":"Заречная","q51":"Донецкая","q52":"пр. Лагутенко","q53":"пр. Дзержинского","q54":"Кальмиусская","q55":"пр. Павших Коммунаров","q57":"Дом 33","pc11":"Копировать","pc20":"Привет из Донецка!","pc28":"Осталось символов: {n}","pc29":"Кому:","pc30":"Открытка из Донецка 2011","pc12":"Привет! Помнишь, как мы гуляли по Пушкинскому бульвару?","pr2":"О проекте","rd0":"Радио","rd3":"Включить","rd11":"Запись","rd13":"Сигнал собран по стандарту, как его генерировала служба времени, и звучит так, как из кухонного репродуктора проводного радио. Свободной записи эфира Украинского радио нет.","rd12":"запись не загрузилась, играет заменитель из браузера","rd4":"Выключить","rd7":"Между станциями только шум. Крути дальше.","rd9":"Включи радио, чтобы услышать.","sd13":"Кассета пока пустая","sd15":"Пауза","u24":"Где проект сейчас","u7":"Сайт","u6":"Игра","ur1":"Заряжает","ur2":"Разряжает","ur3":"Заряд обновления: {p}%","ur4":"Реакции","ur5":"Счётчики недоступны, реакция сохранена у тебя","ur6":"Ещё нет реакций","u5":"Все","u8":"Исследование","u10":"Развернуть всё","u11":"Свернуть всё","u12":"Новое","u13":"Улучшено","u14":"Исправлено","u15":"Подробнее","u16":"Скрыть","u17":"Ссылка скопирована","u18":"Ссылка на запись","u19":"Новых с прошлого визита: {n}","u20":"С прошлого визита ничего нового. Ты видел всё.","u21":"Ты здесь впервые: ниже вся история проекта с первого дня.","u22":"Дней в работе","u23":"Обновлений","u26":"Последнее обновление","u27":"Все обновления →","u28":"Здесь пока пусто: подходящих записей нет.","u30":"сейчас","u32":"Версия сайта","u33":"Этап игры","u34":"Новое","uc1":"Облететь квартал →","uc2":"На главную →","uc3":"Оставить воспоминание →","uc4":"Пройти Заречную →","uc5":"Смотреть фильм →","uc6":"Смотреть блокаут →","uc7":"Открыть фотоархив →","uc8":"Сравнить было и стало →","uc9":"Сыграть в квиз →","cm3":"Сравнить: было и стало","cm4":"Тот же кадр из Unreal до и после прохода по покрытиям и озеленению","q74":"Открыть 3D-квартал"};
